package com.bmd.scanner;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.Bundle;
import android.text.InputType;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.util.Locale;

/** One real two-step wizard shared by the Home scan menu and saved scan sessions. */
final class ScanStartWizard {
    interface Start {void start(String mode,int expected);}
    private final Activity activity;private final Context words;private final Start start;private final Runnable cancel;
    private final ThemeSkin skin;private final String language;
    private String selected="",draft="";private int step=1;private boolean countOnly,finished;
    private android.app.Dialog dialog;private LinearLayout panel;private EditText input;private TextView next;
    ScanStartWizard(Activity activity,String language,Start start,Runnable cancel){this.activity=activity;this.language=language;this.start=start;this.cancel=cancel;skin=ThemeSkin.active;Configuration config=new Configuration(activity.getResources().getConfiguration());config.setLocale(Locale.forLanguageTag(language));words=activity.createConfigurationContext(config);}
    private String s(String key){int id=activity.getResources().getIdentifier("ui_"+key,"string",activity.getPackageName());return id==0?key:words.getString(id);}
    private int dp(float n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView label(String value,int sp,boolean bold){TextView t=new TextView(activity);t.setText(value);t.setTextColor(skin.text);t.setTextSize(sp);t.setIncludeFontPadding(false);t.setTypeface(ReferenceArt.face(activity,false,bold?850:550));return t;}
    private void gap(LinearLayout l,int n){l.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(n)));}
    private GradientDrawable round(int fill,int edge,int radius){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(radius));g.setStroke(dp(1),edge);return g;}
    private TextView action(String value,Runnable run,boolean primary){TextView v=label(value,20,true);v.setGravity(Gravity.CENTER);v.setMinHeight(dp(50));v.setPadding(dp(12),dp(10),dp(12),dp(10));v.setTextColor(primary?(skin==ThemeSkin.LIGHT?Color.WHITE:0xff001b29):skin.text);v.setBackground(primary?new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{skin==ThemeSkin.LIGHT?skin.accent:UiArt.mix(skin.accent,Color.WHITE,.4f),skin==ThemeSkin.LIGHT?UiArt.mix(skin.accent,0xff001b29,.2f):skin.accent}):round(0x66000000,skin.edge,24));if(primary)((GradientDrawable)v.getBackground()).setCornerRadius(dp(24));v.setClickable(true);v.setFocusable(true);v.setOnClickListener(w->{if(android.animation.ValueAnimator.areAnimatorsEnabled()){v.setScaleX(.97f);v.setScaleY(.97f);v.animate().scaleX(1).scaleY(1).setDuration(180).start();}run.run();});return v;}
    ScanStartWizard edit(String mode,int expected){selected="stack".equals(mode)?"stack":"box";draft=Integer.toString(expected);step=2;countOnly=true;return this;}
    void restore(Bundle saved){selected=saved.getString("mode","");if(!selected.equals("box")&&!selected.equals("stack"))selected="";draft=saved.getString("draft","");countOnly=saved.getBoolean("edit");step=saved.getInt("step",1)==2&&!selected.isEmpty()?2:1;}
    Bundle save(){if(input!=null)draft=input.getText().toString();Bundle out=new Bundle();out.putString("mode",selected);out.putString("draft",draft);out.putInt("step",step);out.putBoolean("edit",countOnly);return out;}
    boolean editing(){return countOnly;}
    boolean isShowing(){return dialog!=null&&dialog.isShowing();}
    android.app.Dialog dialog(){return dialog;}
    void show(){androidx.activity.ComponentDialog modal=new androidx.activity.ComponentDialog(activity);modal.getOnBackPressedDispatcher().addCallback(new androidx.activity.OnBackPressedCallback(true){@Override public void handleOnBackPressed(){back();}});dialog=modal;dialog.setCanceledOnTouchOutside(false);dialog.setOnCancelListener(d->{});dialog.setOnDismissListener(d->{if(!finished)cancel.run();});render();dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.setDimAmount(.64f);w.setGravity(Gravity.BOTTOM);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);w.setLayout(-1,-2);}animate();}
    void dispose(){finished=true;if(dialog!=null)dialog.dismiss();}
    void back(){if(step==2&&!countOnly){if(input!=null)draft=input.getText().toString();step=1;render();animate();}else dialog.dismiss();}
    private void animate(){if(panel!=null&&android.animation.ValueAnimator.areAnimatorsEnabled()){panel.setTranslationY(dp(24));panel.setAlpha(0);panel.animate().translationY(0).alpha(1).setDuration(260).start();}}
    private void render(){
        input=null;panel=column();panel.setTag(step==1?"wizard-step-type":"wizard-step-count");panel.setPadding(dp(18),dp(14),dp(18),dp(18));panel.setBackground(new WizardSurface(skin,activity.getResources().getDisplayMetrics().density));panel.setFocusableInTouchMode(true);
        LinearLayout top=new LinearLayout(activity);top.setGravity(Gravity.CENTER_VERTICAL);TextView badge=label(s(step==1?"wizard_step_type":"wizard_step_count"),14,true);badge.setGravity(Gravity.CENTER);badge.setPadding(dp(10),dp(7),dp(10),dp(7));badge.setBackground(round(UiArt.mix(skin.top,0xff7d36ab,.25f),skin.accent,18));LinearLayout.LayoutParams badgeP=new LinearLayout.LayoutParams(0,-2,1);badgeP.setMargins(dp(32),0,0,0);top.addView(badge,badgeP);TextView close=label("×",29,false);close.setGravity(Gravity.CENTER);close.setContentDescription(s("close"));close.setOnClickListener(v->dialog.dismiss());top.addView(close,new LinearLayout.LayoutParams(dp(40),dp(40)));panel.addView(top);
        gap(panel,10);panel.addView(progress(),new LinearLayout.LayoutParams(-1,dp(44)));gap(panel,12);
        TextView question=label(s(step==1?"wizard_type_question":"wizard_count_question"),25,true);question.setGravity(Gravity.CENTER);question.setMaxLines(3);FrameLayout heading=new FrameLayout(activity);heading.addView(new TitleFlourish(activity,skin),new FrameLayout.LayoutParams(-1,-1));question.setPadding(dp(10),dp(4),dp(10),dp(4));heading.addView(question,new FrameLayout.LayoutParams(-1,-2));panel.addView(heading,new LinearLayout.LayoutParams(-1,-2));gap(panel,18);
        if(step==1)typeChoices();else countEntry();
        ScrollView scroll=new ScrollView(activity){@Override protected void onMeasure(int ws,int hs){int screen=(int)(getResources().getDisplayMetrics().heightPixels*.86f),offered=MeasureSpec.getSize(hs);super.onMeasure(ws,MeasureSpec.makeMeasureSpec(offered>0?Math.min(screen,offered):screen,MeasureSpec.AT_MOST));}};scroll.setFillViewport(false);scroll.addView(panel);dialog.setContentView(scroll);panel.requestFocus();
    }
    private View progress(){LinearLayout l=new LinearLayout(activity);String[] titles={s("wizard_type"),s("wizard_count"),s("scan")};for(int n=0;n<3;n++){LinearLayout cell=column();cell.setGravity(Gravity.CENTER);StepDot dot=new StepDot(activity,n<step-1,n==step-1,skin);cell.addView(dot,new LinearLayout.LayoutParams(dp(18),dp(18)));gap(cell,6);TextView text=label(titles[n],12,n==step-1);text.setGravity(Gravity.CENTER);text.setMaxLines(1);text.setAutoSizeTextTypeUniformWithConfiguration(9,12,1,android.util.TypedValue.COMPLEX_UNIT_SP);cell.addView(text,new LinearLayout.LayoutParams(-1,dp(16)));l.addView(cell,new LinearLayout.LayoutParams(0,-1,1));if(n<2){TextView arrow=label("→",17,false);arrow.setTextColor(skin.secondary);arrow.setGravity(Gravity.CENTER);l.addView(arrow,new LinearLayout.LayoutParams(dp(18),-1));}}return l;}
    private void typeChoices(){
        LinearLayout choices=new LinearLayout(activity);for(String mode:new String[]{"box","stack"}){boolean box=mode.equals("box"),chosen=mode.equals(selected);int accent=box?0xff00e3ee:0xffd270ff;FrameLayout frame=new FrameLayout(activity);frame.setTag("wizard-type-"+mode);frame.setSelected(chosen);frame.setContentDescription(s(box?"wizard_box":"wizard_stack"));frame.setClickable(true);frame.setFocusable(true);frame.setBackground(UiArt.raised(box?0xff00c3cc:0xffa527d6,box?0xff003c49:0xff350c54,chosen?skin.accent:accent,dp(20)));LinearLayout content=column();content.setGravity(Gravity.CENTER);content.setPadding(dp(8),dp(9),dp(8),dp(10));ImageView art=new ImageView(activity);art.setImageBitmap(ReferenceArt.bitmap(activity,box?R.drawable.wizard_full_box:R.drawable.wizard_stack));art.setScaleType(ImageView.ScaleType.FIT_CENTER);content.addView(art,new LinearLayout.LayoutParams(-1,dp(82)));TextView title=label(s(box?"wizard_box":"wizard_stack"),19,true);title.setTextColor(Color.WHITE);title.setGravity(Gravity.CENTER);title.setMaxLines(2);title.setAutoSizeTextTypeUniformWithConfiguration(13,19,1,android.util.TypedValue.COMPLEX_UNIT_SP);content.addView(title,new LinearLayout.LayoutParams(-1,dp(44)));TextView hint=label(s(box?"wizard_box_hint":"wizard_stack_hint"),12,false);hint.setTextColor(0xffe3eff9);hint.setGravity(Gravity.CENTER);hint.setMaxLines(4);hint.setAutoSizeTextTypeUniformWithConfiguration(10,12,1,android.util.TypedValue.COMPLEX_UNIT_SP);content.addView(hint,new LinearLayout.LayoutParams(-1,dp(56)));frame.addView(content,new FrameLayout.LayoutParams(-1,-1));
            if(chosen){TextView check=label("✓",22,true);check.setTextColor(0xff002e0c);check.setGravity(Gravity.CENTER);check.setBackground(round(0xff66ff31,0xffbcff9b,20));FrameLayout.LayoutParams mark=new FrameLayout.LayoutParams(dp(32),dp(32),Gravity.TOP|Gravity.END);mark.setMargins(0,dp(3),dp(3),0);frame.addView(check,mark);}frame.setOnClickListener(v->{selected=mode;render();animate();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(210),1);p.setMargins(box?0:dp(5),0,box?dp(5):0,0);choices.addView(frame,p);}
        panel.addView(choices,new LinearLayout.LayoutParams(-1,-2));gap(panel,14);TextView hint=label(s("wizard_next_count"),13,false);hint.setGravity(Gravity.CENTER);panel.addView(hint,new LinearLayout.LayoutParams(-1,-2));gap(panel,16);next=action(s("wizard_next")+"  ›",()->{if(selected.isEmpty())return;step=2;render();animate();},true);next.setTag("wizard-next");next.setEnabled(!selected.isEmpty());next.setAlpha(selected.isEmpty()?.45f:1);panel.addView(next,new LinearLayout.LayoutParams(-1,-2));
    }
    private void countEntry(){
        TextView mode=label(s(selected.equals("stack")?"wizard_stack":"wizard_box"),16,true);mode.setGravity(Gravity.CENTER);mode.setTextColor(Color.WHITE);mode.setPadding(dp(12),dp(7),dp(12),dp(7));mode.setBackground(round(0x88000000,skin.accent,20));mode.setTag("wizard-selected-mode");panel.addView(mode,new LinearLayout.LayoutParams(-1,-2));gap(panel,10);ImageView art=new ImageView(activity);art.setImageBitmap(ReferenceArt.bitmap(activity,selected.equals("stack")?R.drawable.wizard_stack:R.drawable.wizard_full_box));art.setScaleType(ImageView.ScaleType.FIT_CENTER);panel.addView(art,new LinearLayout.LayoutParams(-1,dp(68)));gap(panel,9);
        LinearLayout number=new LinearLayout(activity);number.setGravity(Gravity.CENTER_VERTICAL);number.setPadding(dp(10),dp(8),dp(8),dp(8));number.setBackground(round(0xa0000000,skin.accent,18));LinearLayout labels=column();input=new EditText(activity);input.setTag("box-expected-input");input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(10)});input.setTextColor(Color.WHITE);input.setHintTextColor(0xffa8bac8);input.setTextSize(38);input.setTypeface(ReferenceArt.face(activity,false,850));input.setGravity(Gravity.CENTER);input.setPadding(0,0,0,0);input.setBackgroundColor(Color.TRANSPARENT);input.setHint("—");input.setText(draft);input.setContentDescription(s("wizard_products"));labels.addView(input,new LinearLayout.LayoutParams(-1,dp(52)));TextView caption=label(s("wizard_products"),13,false);caption.setTextColor(0xffd0dce5);caption.setGravity(Gravity.CENTER);labels.addView(caption,new LinearLayout.LayoutParams(-1,-2));number.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView keypad=label("▦",31,true);keypad.setTextColor(skin.accent);keypad.setGravity(Gravity.CENTER);keypad.setContentDescription(s("wizard_products"));keypad.setOnClickListener(v->{input.requestFocus();((InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);});number.addView(keypad,new LinearLayout.LayoutParams(dp(44),dp(54)));panel.addView(number,new LinearLayout.LayoutParams(-1,-2));input.setOnEditorActionListener((v,id,event)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_DONE){submit();return true;}return false;});input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);
        gap(panel,12);TextView hint=label(s("wizard_count_hint"),13,false);hint.setGravity(Gravity.CENTER);panel.addView(hint);gap(panel,10);TextView usage=label(s("wizard_count_usage"),12,false);usage.setGravity(Gravity.CENTER);usage.setTextColor(skin.secondary);panel.addView(usage);gap(panel,18);
        LinearLayout actions=new LinearLayout(activity);TextView back=action("‹  "+s("back"),this::back,false);back.setTag("wizard-back");LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,.38f);bp.rightMargin=dp(8);actions.addView(back,bp);next=action(s("wizard_next")+"  ›",this::submit,true);next.setTag("wizard-next");actions.addView(next,new LinearLayout.LayoutParams(0,-2,.62f));panel.addView(actions);
    }
    private void submit(){if(finished)return;try{int n=Integer.parseInt(input.getText().toString().trim());if(n<1||n>10000)throw new NumberFormatException();draft=Integer.toString(n);finished=true;dialog.dismiss();start.start(selected,n);}catch(NumberFormatException e){input.setError(s("count_invalid"));input.requestFocus();}}
    private static final class TitleFlourish extends View {final ThemeSkin skin;final Paint p=new Paint(3);TitleFlourish(Context c,ThemeSkin skin){super(c);this.skin=skin;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(0xffffd239);float x=w*.025f,y=h*.25f,r=4*getResources().getDisplayMetrics().density;Path q=new Path();q.moveTo(x,y-r);q.quadTo(x+r*.2f,y-r*.2f,x+r,y);q.quadTo(x+r*.2f,y+r*.2f,x,y+r);q.quadTo(x-r*.2f,y+r*.2f,x-r,y);q.quadTo(x-r*.2f,y-r*.2f,x,y-r);c.drawPath(q,p);}}
    private static final class StepDot extends View {final boolean done,active;final ThemeSkin skin;final Paint p=new Paint(3);StepDot(Context c,boolean done,boolean active,ThemeSkin skin){super(c);this.done=done;this.active=active;this.skin=skin;}@Override protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)-2;p.setColor(done?0xff5dff32:active?skin.accent:skin.edge);p.setStyle(Paint.Style.FILL);c.drawCircle(x,y,r,p);p.setColor(done?0xff00370b:skin.background);c.drawCircle(x,y,r*.65f,p);if(done){p.setColor(0xff57ff20);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);Path q=new Path();q.moveTo(x-r*.4f,y);q.lineTo(x-r*.08f,y+r*.3f);q.lineTo(x+r*.45f,y-r*.3f);c.drawPath(q,p);}}}
    private static final class WizardSurface extends Drawable {final ThemeSkin skin;final float density;final Paint p=new Paint(3);WizardSurface(ThemeSkin skin,float density){this.skin=skin;this.density=density;}@Override public void draw(Canvas c){Rect r=getBounds();float d=density,rr=25*d;p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,r.top,r.right,r.bottom,new int[]{skin.top,skin.bottom,skin.background},null,Shader.TileMode.CLAMP));c.drawRoundRect(new RectF(r),rr,rr,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2*d);p.setColor(skin.accent);RectF inset=new RectF(r);inset.inset(d,d);c.drawRoundRect(inset,rr,rr,p);p.setStrokeWidth(d);p.setShader(new LinearGradient(0,r.top,r.right,r.bottom,new int[]{Color.WHITE,skin.accent,0xffb868df},null,Shader.TileMode.CLAMP));c.drawRoundRect(inset,rr,rr,p);p.setShader(null);p.setStyle(Paint.Style.FILL);}@Override public void setAlpha(int a){p.setAlpha(a);}@Override public void setColorFilter(ColorFilter f){p.setColorFilter(f);}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
}
